from orders.db import get_conn


def get_order(order_id):
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, customer_id, total_cents, status FROM orders WHERE id = :id",
            {"id": order_id},
        )
    finally:
        conn.close()
    if not rows:
        return None
    r = rows[0]
    return {"id": r["id"], "customer_id": r["customer_id"], "total_cents": r["total_cents"], "status": r["status"]}


def list_orders_for_customer(customer_id):
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, total_cents, status FROM orders WHERE customer_id = :cid ORDER BY id",
            {"cid": customer_id},
        )
    finally:
        conn.close()
    return [{"id": r["id"], "total_cents": r["total_cents"], "status": r["status"]} for r in rows]


def create_order(customer_id, total_cents):
    conn = get_conn()
    try:
        row = conn.execute(
            "INSERT INTO orders (customer_id, total_cents, status) VALUES (:c, :t, 'new') RETURNING id",
            {"c": customer_id, "t": total_cents},
        )[0]
        new_id = row["id"]
    finally:
        conn.close()
    return new_id
